            background: linear-gradient(rgba(15, 25, 35, 0.85), rgba(26, 39, 51, 0.9)), url('https://images.unsplash.com/photo-1554299846-76e788c4f7ad?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1920&q=80');
            background-size: cover;
            background-position: center;
            display: flex;
            align-items: center;
            text-align: center;
            position: relative;
            overflow: hidden;
        }

        .hero::before {
            content: "";
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: radial-gradient(circle at 30% 40%, rgba(179, 150, 88, 0.15) 0%, transparent 30%),
                        radial-gradient(circle at 70% 70%, rgba(30, 45, 60, 0.4) 0%, transparent 40%);
            z-index: 1;
        }

        .hero-content {
            max-width: 800px;
            margin: 0 auto;
            padding-top: 60px;
            position: relative;
            z-index: 2;
        }

        .hero h1 {
            font-family: 'Orbitron', sans-serif;
            font-size: 5.5rem;
            font-weight: 900;
            margin-bottom: 20px;
            text-transform: uppercase;
            background: linear-gradient(to right, var(--accent), #e6c07b, var(--accent));
            -webkit-background-clip: text;
            background-clip: text;
            color: transparent;
            letter-spacing: -2px;
            line-height: 1.1;
            text-shadow: 0 0 15px rgba(179, 150, 88, 0.5);
        }

        .hero p {
            font-size: 1.5rem;
            margin-bottom: 40px;
            color: var(--text-gray);
            max-width: 700px;
            margin-left: auto;
            margin-right: auto;
        }

        .cta-buttons {
            display: flex;
            justify-content: center;
            gap: 20px;
            margin-top: 30px;
        }

        .btn {
            padding: 15px 40px;
            border: none;
            border-radius: 4px;
            font-family: 'Orbitron', sans-serif;
            font-weight: 700;
            font-size: 1.1rem;
            cursor: pointer;
            transition: var(--transition);
            text-transform: uppercase;
            letter-spacing: 1px;
            position: relative;
            overflow: hidden;
        }

        .btn::after {
            content: "";
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.3);
            z-index: 1;
            transition: var(--transition);
        }

        .btn:hover::after {
            transform: scaleX(0);
            transform-origin: left;
        }

        .btn span {
            position: relative;
            z-index: 2;
        }

        .btn-primary {
            background: var(--accent);
            color: var(--primary);
        }

        .btn-primary:hover {
            background: var(--accent-dark);
            transform: translateY(-3px);
            box-shadow: 0 10px 20px rgba(0, 0, 0, 0.3);
        }

        .btn-secondary {
            background: transparent;
            border: 2px solid var(--accent);
            color: var(--accent);
        }

        .btn-secondary:hover {
            background: rgba(179, 150, 88, 0.15);
            transform: translateY(-3px);
            box-shadow: 0 5px 15px rgba(179, 150, 88, 0.3);
        }

        /* Section Styling */
        section {
            padding: 100px 0;
        }

        .section-title {
            text-align: center;
            margin-bottom: 70px;
        }

        .section-title h2 {
            font-family: 'Orbitron', sans-serif;
            font-size: 3.2rem;
            display: inline-block;
            position: relative;
            padding-bottom: 15px;
        }

        .section-title h2::after {
            content: "";
            position: absolute;
            bottom: 0;
            left: 50%;
            transform: translateX(-50%);
            width: 70%;
            height: 3px;
            background: var(--accent);
            border-radius: 3px;
        }

        .section-title p {
            color: var(--text-gray);
            font-size: 1.2rem;
            margin-top: 15px;
        }

        /* Weapons Section */
        .weapons-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
            gap: 30px;
            margin-top: 30px;
        }

        .weapon-card {
            background: var(--card-bg);
            border-radius: 8px;
            overflow: hidden;
            box-shadow: var(--shadow);
            transition: var(--transition);
            position: relative;
        }

        .weapon-card:hover {
            transform: translateY(-10px);
            box-shadow: 0 15px 35px rgba(0, 0, 0, 0.6);
        }

        .weapon-img {
            height: 200px;
            width: 100%;
            background-size: cover;
            background-position: center;
            position: relative;
            overflow: hidden;
        }

        .weapon-img::after {
            content: "";
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: linear-gradient(rgba(15, 25, 35, 0.7), rgba(26, 39, 51, 0.9));
            opacity: 0;
            transition: var(--transition);
        }

        .weapon-card:hover .weapon-img::after {
            opacity: 1;
        }

        .weapon-img.ak47 { background-image: url('https://images.unsplash.com/photo-1598193955610-4f9f8e809f58?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=600&q=80'); }
        .weapon-img.awp { background-image: url('https://images.unsplash.com/photo-1612349318773-2aa4e29b226c?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=600&q=80'); }
        .weapon-img.deagle { background-image: url('https://images.unsplash.com/photo-1550748044-4341f9d19c45?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=600&q=80'); }
        .weapon-img.knife { background-image: url('https://images.unsplash.com/photo-1598193955410-4f9f8e809f58?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=600&q=80'); }

        .weapon-info {
            padding: 20px;
        }

        .weapon-info h3 {
            font-family: 'Orbitron', sans-serif;
            font-size: 1.6rem;
            margin-bottom: 10px;
            color: var(--accent);
        }

        .weapon-info p {
            color: var(--text-gray);
            margin-bottom: 15px;
            font-size: 0.95rem;
        }

        .weapon-rarity {
            display: inline-block;
            padding: 3px 10px;
            border-radius: 15px;
            font-size: 0.8rem;
            font-weight: 700;
            letter-spacing: 1px;
        }

        .rarity-covert {
            background: linear-gradient(45deg, #eb455f, #d93047);
            color: white;
        }

        .rarity-classified {
            background: linear-gradient(45deg, #e05e26, #c84a1b);
            color: white;
        }

        .rarity-restricted {
            background: linear-gradient(45deg, #a855f7, #8b3dff);
            color: white;
        }

        /* Tournaments Section */
        .tournaments {
            background: rgba(20, 30, 40, 0.9);
            position: relative;
            overflow: hidden;
        }

        .tournaments::before {
            content: "";
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-image: 
                radial-gradient(circle at 15% 30%, rgba(30, 45, 60, 0.4) 0%, transparent 25%),
                radial-gradient(circle at 85% 70%, rgba(45, 30, 60, 0.4) 0%, transparent 25%);
            z-index: 0;
        }

        .tournament-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
            gap: 35px;
            position: relative;
            z-index: 1;
        }

        .tournament-card {
            background: var(--card-bg);
            border-radius: 8px;
            overflow: hidden;
            box-shadow: var(--shadow);
            transition: var(--transition);
            border: 1px solid rgba(179, 150, 88, 0.2);
        }

        .tournament-card:hover {
            transform: translateY(-5px);
            border-color: var(--accent);
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.6);
        }

        .tournament-header {
            padding: 20px;
            background: rgba(26, 39, 51, 0.9);
            text-align: center;
            border-bottom: 2px solid var(--accent);
        }

        .tournament-header h3 {
            font-family: 'Orbitron', sans-serif;
            font-size: 1.8rem;
            color: var(--accent);
        }

        .tournament-date {
            color: var(--text-gray);
            margin-top: 5px;
            font-size: 0.95rem;
        }

        .tournament-body {
            padding: 25px;
        }

        .tournament-body p {
            margin-bottom: 15px;
            color: var(--text-gray);
        }

        .prize-pool {
            font-family: 'Orbitron', sans-serif;
            font-size: 1.7rem;
            color: var(--accent);
            text-align: center;
            margin: 15px 0;
            font-weight: 700;
        }

        .teams-list {
            display: flex;
            justify-content: space-between;
            margin-top: 20px;
            padding-top: 15px;
            border-top: 1px solid rgba(179, 150, 88, 0.3);
        }

        .team {
            text-align: center;
            flex: 1;
        }

        .team img {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            object-fit: cover;
            border: 2px solid var(--accent);
            margin-bottom: 8px;
        }

        .team-name {
            font-size: 0.85rem;
            font-weight: 500;
        }

        /* Stats Section */
        .stats-container {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 30px;
            text-align: center;
            margin-top: 50px;
        }

        .stat-item {
            padding: 25px 15px;
            background: var(--card-bg);
            border-radius: 8px;
            box-shadow: var(--shadow);
            transition: var(--transition);
        }

        .stat-item:hover {
            transform: translateY(-5px);
        }

        .stat-number {
            font-family: 'Orbitron', sans-serif;
            font-size: 3.5rem;
            font-weight: 800;
            color: var(--accent);
            margin: 10px 0;
            line-height: 1;
        }

        .stat-label {
            font-size: 1.2rem;
            color: var(--text-gray);
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        /* Footer */
        footer {
            background: rgba(10, 15, 22, 0.95);
            padding: 70px 0 0;
            position: relative;
            border-top: 1px solid rgba(179, 150, 88, 0.3);
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 40px;
            margin-bottom: 50px;
        }

        .footer-col h3 {
            font-family: 'Orbitron', sans-serif;
            font-size: 1.8rem;
            margin-bottom: 25px;
            position: relative;
            padding-bottom: 10px;
            display: inline-block;
        }

        .footer-col h3::after {
            content: "";
            position: absolute;
            bottom: 0;
            left: 0;
            width: 40%;
            height: 2px;
            background: var(--accent);
        }

        .footer-col p {
            color: var(--text-gray);
            margin: 15px 0;
            line-height: 1.7;
        }

        .social-links {
            display: flex;
            gap: 15px;
            margin-top: 20px;
        }

        .social-links a {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background: var(--secondary);
            color: var(--accent);
            font-size: 1.2rem;
            transition: var(--transition);
            border: 1px solid var(--accent);
        }

        .social-links a:hover {
            background: var(--accent);
            color: var(--primary);
            transform: translateY(-3px);
        }

